/**
 * Worker environment. `Env` (bindings) is generated by `wrangler types` into
 * worker-configuration.d.ts; secrets are declared here because they are not in wrangler.jsonc.
 */
declare global {
  namespace Cloudflare {
    interface Env {
      SESSION_SECRET: string;
      ENCRYPTION_KEY: string;
    }
  }
}

export type AppEnv = {
  Bindings: Env;
  Variables: {
    /** Set by the auth middleware on authenticated requests. */
    authenticated: boolean;
  };
};

export const isDemo = (env: Env): boolean => env.DEMO_MODE === '1';
